      { id: 48, game_number: 8, title: "Tax Planner", description: "Calculate taxes and optimize financial strategy.", lesson: "Taxation & Tax Planning", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
      { id: 49, game_number: 9, title: "Labor Economics", description: "Understand wages, employment, and worker rights.", lesson: "Labor Economics", base_reward: 150, coin_cost: 20, difficulty: "Hard" },
